    wordCount: 'Reader document word count',
    readingProgress: 'Reader reading progress as a fraction from 0 to 1',
    readerLocation: 'Reader location of the document: new, later, shortlist, archive, or feed',
    // Source-agnostic annotations (Zotero PDF annotations, Readwise highlights, …)
    annotations: 'Annotations from any source (Zotero PDF annotations, Readwise highlights). Iterate with {{#each annotations}} — each item has text, comment, type, color, colorName, page, pageLabel, tags, imagePath, openURI, source',
    highlights: 'Deprecated — use {{#each annotations}} instead. Legacy Readwise-only highlight list (text, note, location, locationType, color, highlightedAt, url, tags), kept for backward compatibility with existing templates.',
