/** Built-in note kind — the only one implemented currently. */
const DEFAULT_NOTE_KIND = {
    id: 'literature-note',
    name: 'Literature Note',
    folder: 'Reading notes',
};
/** Default profile — backward compatible with existing settings. */
const DEFAULT_PROFILE = {
    id: 'default',
    noteKind: 'literature-note',
    entryTypes: ['*'],
    titleTemplate: '@{{citekey}}',
    contentTemplatePath: 'citation-content-template.md',
};

class TemplateProfileRegistry {
    constructor(defaultProfile) {
        this.profiles = [];
        this.noteKinds = [];
        this.defaultProfile = defaultProfile ?? DEFAULT_PROFILE;
        this.noteKinds.push(DEFAULT_NOTE_KIND);
    }
    register(profile) {
        // Replace existing profile with same id
        const index = this.profiles.findIndex((p) => p.id === profile.id);
        if (index !== -1) {
            this.profiles[index] = profile;
        }
        else {
            this.profiles.push(profile);
        }
    }
    registerNoteKind(kind) {
        if (!this.noteKinds.some((k) => k.id === kind.id)) {
            this.noteKinds.push(kind);
        }
    }
    resolve(noteKind, entryType) {
        // 1. Exact match: noteKind matches AND entryType is in the list
        const exact = this.profiles.find((p) => p.noteKind === noteKind && p.entryTypes.includes(entryType));
        if (exact)
            return exact;
        // 2. Wildcard match: noteKind matches AND entryTypes contains '*'
        const wildcard = this.profiles.find((p) => p.noteKind === noteKind && p.entryTypes.includes('*'));
        if (wildcard)
            return wildcard;
        // 3. Default profile
        return this.defaultProfile;
    }
    getProfiles() {
        return [...this.profiles];
    }
    getNoteKinds() {
        return [...this.noteKinds];
    }
    getDefaultProfile() {
        return this.defaultProfile;
    }
}

