class CitationService {
    constructor(libraryService, templateService, contentTemplateResolver, settings) {
        this.libraryService = libraryService;
        this.templateService = templateService;
        this.contentTemplateResolver = contentTemplateResolver;
        this.settings = settings;
    }
    getEntry(citekey) {
        const library = this.libraryService.library;
        if (this.libraryService.isLibraryLoading || !library) {
            return err(new LibraryNotReadyError());
        }
        const entry = library.entries[citekey];
        if (!entry) {
            return err(new EntryNotFoundError(citekey));
        }
        return ok(entry);
    }
    getTitleForCitekey(citekey) {
        const entryResult = this.getEntry(citekey);
        if (!entryResult.ok)
            return entryResult;
        const variables = this.templateService.getTemplateVariables(entryResult.value);
        const titleResult = this.templateService.getTitle(variables);
        if (!titleResult.ok)
            return titleResult;
        return ok(titleResult.value.replace(DISALLOWED_FILENAME_CHARACTERS_RE, this.settings.filenameSanitizationReplacement));
    }
    async getInitialContentForCitekey(citekey, selectedText) {
        const entryResult = this.getEntry(citekey);
        if (!entryResult.ok)
            return entryResult;
        const variables = this.templateService.getTemplateVariables(entryResult.value, { selectedText });
        const templateStr = await this.contentTemplateResolver.resolve();
        return this.templateService.render(templateStr, variables);
    }
    getMarkdownCitation(citekey, alternative = false, selectedText) {
        const entryResult = this.getEntry(citekey);
        if (!entryResult.ok)
            return entryResult;
        const variables = this.templateService.getTemplateVariables(entryResult.value, { selectedText });
        return this.templateService.getMarkdownCitation(variables, alternative);
    }
}

